<h2>Organograma por vínculo</h2><p>A hierarquia abaixo mostra os vínculos ativos e afastados. Cada nível liga a pessoa ao responsável registrado nesta empresa.</p>
<?php
$children=[];foreach($chart['employees'] as $r)$children[(int)($r['manager_id']??0)][]=$r;$seen=[];
$branch=function(int $parent,int $depth=0)use(&$branch,&$seen,$children,$esc,$options,$url):void{if($depth>64||!isset($children[$parent]))return;echo '<ul class="hr-hierarchy">';foreach($children[$parent] as $r){$id=(int)$r['id'];if(isset($seen[$id]))continue;$seen[$id]=true;echo '<li data-employee-id="'.$id.'"><span class="hr-node"><a href="'.$esc($url(['section'=>'people','employee'=>$id])).'">'.$esc($r['name']).'</a><small>'.$esc($options['position'][$r['position_id']]??'').' · '.$esc($options['unit'][$r['unit_id']]??'').'</small></span>';$branch($id,$depth+1);echo '</li>';}echo '</ul>';};
?><div id="hr-hierarchy" aria-label="Hierarquia dos vínculos"><?php $branch(0); ?></div><details><summary>Conferir vínculos em tabela</summary><table class="table" id="hr-org-chart"><thead><tr><th>Pessoa</th><th>Unidade</th><th>Cargo</th><th>Responsável</th></tr></thead><tbody><?php foreach($chart['employees'] as $r){?><tr><td><?= $esc($r['name']); ?></td><td><?= $esc($options['unit'][$r['unit_id']]??''); ?></td><td><?= $esc($options['position'][$r['position_id']]??''); ?></td><td><?= $esc($people[$r['manager_id']]??'Sem responsável'); ?></td></tr><?php } ?></tbody></table></details>
