<?php }elseif($section==='articles'){?><h2>Orientações internas</h2><p>Textos simples desta empresa. Publicar disponibiliza a orientação em “Meu RH” para pessoas com vínculo ativo.</p><?php foreach(array_merge($articles,$can('hr','configure')?[null]:[]) as $r){?><details><summary><?= $r===null?'Nova orientação':$esc($r['title']); ?></summary><?php if($can('hr','configure')){echo form_open($url());$hidden('article_save',['entity_id'=>$r['id']??'','revision'=>$r['revision']??'']);$field('Título','input[title]',$r['title']??'','text','required maxlength="191"');$area('Orientação','input[body]',$r['body']??'',7);$select('Disponibilidade','input[published]',['0'=>'Rascunho','1'=>'Publicada'],$r['published']??0);?><button type="submit">Salvar orientação</button><?= form_close(); ?><?php }else{?><p><?= nl2br($esc($r['body'])); ?></p><?php } ?><?php if($r!==null&&$can('hr_files','view')){?><a href="<?= $esc($url(['files_purpose'=>'article','files_object'=>$r['id']])); ?>">Documentos de apoio</a><?php } ?></details><?php } ?>
<?php }elseif($section==='reports'){?><h2>Relatórios</h2><nav class="company-settings-nav"><?php foreach(['roster'=>'Vínculos','seniority'=>'Tempo de vínculo','turnover'=>'Admissões e desligamentos','education'=>'Qualificações','equipment'=>'Equipamentos','compensation'=>'Alterações de valores','contracts'=>'Contratos','training'=>'Treinamentos'] as $name=>$label){if(in_array($name,['education','equipment','compensation','contracts'],true)&&!$can('hr_sensitive','view'))continue;if($name==='contracts'&&!$can('hr_contracts','view'))continue;if($name==='training'&&!$can('hr_training','view'))continue;?><a href="<?= $esc($url(['report'=>$name])); ?>"><?= $esc($label); ?></a><?php } ?></nav>
<?php if($report!==null){?><p><?= (int)$report['count']; ?> linhas, referência <?= $esc($report['as_of']); ?>. Dias são diferenças entre datas civis, limitadas a zero; desligamentos são registros individuais. Não há apuração legal de folha ou taxa estatística de rotatividade.</p><?php if($can('hr','export')){?><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'staff/hr_export?report='.$report['report'])); ?>">Baixar CSV deste relatório</a><?php } ?><div class="table-responsive"><table class="table" id="hr-report"><thead><tr><?php foreach(array_keys($report['rows'][0]??[]) as $head){?><th><?= $esc($reportLabels[$head]??$head); ?></th><?php } ?></tr></thead><tbody><?php foreach($report['rows'] as $row){?><tr><?php foreach($row as $value){?><td><?= $esc(is_array($value)?json_encode($value,JSON_UNESCAPED_UNICODE):$value); ?></td><?php } ?></tr><?php } ?></tbody></table></div><?php } ?>
<?php }else{?><h2>Importar vínculos revisados</h2><p>CSV UTF-8 com até 100 linhas e 256 KiB. As pessoas precisam estar na equipe desta empresa. Cabeçalho exato:</p><p><code>staff_id,employee_code,unit_id,position_id,workplace_id,manager_id,joined_on,state,left_on</code></p><p>Datas usam AAAA-MM-DD; situação usa active, on_leave ou terminated. Código, unidade, cargo e local precisam ser conferidos antes da confirmação.</p><?= form_open_multipart($url(),['id'=>'hr-import-review']);$hidden('import_review');?><label>Arquivo CSV <input name="csv" type="file" accept=".csv,text/csv" required></label><button type="submit">Revisar importação</button><?= form_close(); ?>
<?php if($preview!==null){?><h3>Revisão de <?= (int)$preview['count']; ?> vínculos</h3><table class="table"><thead><tr><th>Pessoa</th><th>Código</th><th>Unidade</th><th>Cargo</th><th>Admissão</th></tr></thead><tbody><?php foreach($preview['rows'] as $r){?><tr><td>#<?= (int)$r['staff_id']; ?></td><td><?= $esc($r['employee_code']); ?></td><td><?= $esc($options['unit'][$r['unit_id']]??''); ?></td><td><?= $esc($options['position'][$r['position_id']]??''); ?></td><td><?= $esc($r['joined_on']); ?></td></tr><?php } ?></tbody></table><?= form_open($url(),['id'=>'hr-import-confirm']);$hidden('import_commit');?><input type="hidden" name="input[content_base64]" value="<?= $esc($preview['content_base64']); ?>"><input type="hidden" name="input[review_hash]" value="<?= $esc($preview['review_hash']); ?>"><button type="submit">Confirmar todos os vínculos revisados</button><?= form_close(); ?><?php } ?>
<?php } ?>
<?php if($file_context!==null){?><section id="hr-files"><h2>Arquivos privados deste registro</h2><p>PDF até 2 MiB ou imagem PNG/JPEG normalizada. Limite de 20 arquivos e 20 MiB por registro, incluindo arquivos ocultos.</p><table class="table"><thead><tr><th>Documento</th><th>Tamanho</th><th>Ações</th></tr></thead><tbody><?php foreach($files as $f){?><tr><td><?= $esc($f['name']); ?><?= (int)$f['hidden']===1?' · oculto':''; ?></td><td><?= (int)$f['size']; ?> bytes</td><td><?php if((int)$f['hidden']===0){?><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'staff/hr_file?'.http_build_query(['purpose'=>$file_context['purpose'],'object'=>$file_context['object_id'],'file'=>$f['id']]))); ?>">Baixar</a><?php if($can('hr_files','delete')){echo form_open($url(['employee'=>$employee['id']??null,'files_purpose'=>$file_context['purpose'],'files_object'=>$file_context['object_id']]));$hidden('file_hide',['entity_id'=>$f['id'],'revision'=>$f['revision']]);?><input type="hidden" name="input[purpose]" value="<?= $esc($file_context['purpose']); ?>"><input type="hidden" name="input[object_id]" value="<?= (int)$file_context['object_id']; ?>"><button type="submit">Ocultar</button><?= form_close(); ?><?php }} ?></td></tr><?php } ?></tbody></table>
<?php if($can('hr_files','create')){echo form_open_multipart($url(['employee'=>$employee['id']??null,'files_purpose'=>$file_context['purpose'],'files_object'=>$file_context['object_id']]),['id'=>'hr-file-upload']);$hidden('file_upload',['revision'=>$file_context['revision']]);?><input type="hidden" name="input[purpose]" value="<?= $esc($file_context['purpose']); ?>"><input type="hidden" name="input[object_id]" value="<?= (int)$file_context['object_id']; ?>"><label>Documento <input type="file" name="document" accept="application/pdf,image/png,image/jpeg" required></label><button type="submit">Adicionar documento</button><?= form_close(); ?><?php } ?></section><?php } ?>
</section>
<script>document.querySelectorAll('.hr-add-question').forEach(button=>button.addEventListener('click',()=>{const box=button.previousElementSibling;const count=box.children.length;if(count>=30)return;const row=box.firstElementChild.cloneNode(true);row.querySelector('legend').textContent='Questão '+(count+1);row.querySelectorAll('input,textarea').forEach((field,index)=>{const old=field.id;field.name=field.name.replace(/\[questions\]\[\d+\]/,'[questions]['+count+']');field.id=old+'-q'+count+'-'+index;const label=Array.from(row.querySelectorAll('label')).find(item=>item.htmlFor===old);if(label)label.htmlFor=field.id;field.value=field.type==='number'?'1':'';});box.appendChild(row);}));</script>
